using System.Text;

namespace OpenScct.CodeGen.Emit;

/// <summary>An indenting text writer that always writes LF line endings and four-space indents.</summary>
internal sealed class CodeWriter
{
    private readonly StringBuilder _sb = new();
    private int _indent;

    public const string Header =
        "// <auto-generated>\n" +
        "//     Generated by tools/OpenScct.CodeGen (see docs/CODEGEN.md). Do not edit by hand: change the generator or its\n" +
        "//     inputs and run it again.\n" +
        "// </auto-generated>\n";

    public CodeWriter Line(string text = "")
    {
        if (text.Length == 0)
        {
            _sb.Append('\n');
            return this;
        }

        _sb.Append(' ', _indent * 4).Append(text).Append('\n');
        return this;
    }

    public CodeWriter Open(string text)
    {
        Line(text);
        Line("{");
        _indent++;
        return this;
    }

    public CodeWriter Close(string suffix = "")
    {
        _indent--;
        Line("}" + suffix);
        return this;
    }

    public CodeWriter Indent()
    {
        _indent++;
        return this;
    }

    public CodeWriter Outdent()
    {
        _indent--;
        return this;
    }

    public override string ToString() => _sb.ToString();
}
